suppressPackageStartupMessages(library(limma))
B<-'/mnt/BioDisk/wangmingyuan/GI_preanalysis_20260923';R<-file.path(B,'GC_validation_v2');O<-file.path(R,'04_results','bulk_robustness');dir.create(O,recursive=TRUE,showWarnings=FALSE)
x<-read.delim(gzfile(file.path(B,'03_processed','GC314812_TMM_logCPM.tsv.gz')),check.names=FALSE);m<-read.delim(file.path(B,'04_results','GC_bulk','paired_sample_qc.tsv'),check.names=FALSE);E<-as.matrix(x[,m$sample]);rownames(E)<-x$gene_id;sy<-x$symbol;m$patient<-factor(m$patient);m$site<-factor(m$site,levels=c('GCPT','GCPM'));m$preservation<-factor(m[['preservation method']])
gs<-c('CD36','FABP4','FABP5','SLC27A1','SLC27A2','SLC27A4','LDLR','LPL');score<-function(g)colMeans(E[sy%in%g,,drop=FALSE]);m$lipid<-score(gs)
calc<-function(m,out='lipid',extra=NULL){fo<-as.formula(paste(out,'~patient+preservation',if(!is.null(extra))paste0('+',paste(extra,collapse='+'))else'','+site'));fit<-lm(fo,data=m);z<-coef(summary(fit))['siteGCPM',];c(effect=z[1],SE=z[2],P=z[4],df=df.residual(fit),lo=z[1]-qt(.975,df.residual(fit))*z[2],hi=z[1]+qt(.975,df.residual(fit))*z[2])}
main<-calc(m);write.table(data.frame(metric=names(main),value=main),file.path(O,'primary_effect_CI.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
loo<-lapply(gs,function(g){mm<-m;mm$lipid<-score(setdiff(gs,g));z<-calc(mm);data.frame(omitted_gene=g,t(z),check.names=FALSE)});loo<-do.call(rbind,loo);loo$FDR_BH_sensitivity_family<-p.adjust(loo$P,'BH');write.table(loo,file.path(O,'leave_one_gene_out.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
lop<-lapply(levels(m$patient),function(id){z<-calc(droplevels(m[m$patient!=id,]));data.frame(omitted_patient=id,effect=z['effect.Estimate'],SE=z['SE.Std. Error'],check.names=FALSE)});lop<-do.call(rbind,lop);write.table(lop,file.path(O,'leave_one_patient_out.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
# Independent proxy genes do not overlap tested lipid panel.
sets<-list(adipocyte=c('ADIPOQ','PLIN1','CIDEC','CIDEA','LEP'),myeloid=c('CSF1R','CD68','C1QB','AIF1','CD163','LYZ'),epithelial=c('EPCAM','KRT8','KRT18','KRT19'),stroma=c('COL1A1','COL1A2','COL3A1','DCN','LUM','FAP','PDGFRA'))
for(n in names(sets))m[[n]]<-score(sets[[n]])
write.table(data.frame(program=names(sets),genes=sapply(sets,paste,collapse=';'),measured=sapply(sets,function(z)sum(sy%in%z))),file.path(O,'proxy_gene_sets.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
models<-list(adipocyte='adipocyte',myeloid='myeloid',epithelial='epithelial',stroma='stroma',adipocyte_myeloid=c('adipocyte','myeloid'));rr<-do.call(rbind,lapply(names(models),function(n)data.frame(model=n,t(calc(m,extra=models[[n]])),check.names=FALSE)));rr$FDR_BH_sensitivity_family<-p.adjust(rr$P,'BH');write.table(rr,file.path(O,'composition_proxy_sensitivity.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
id<-levels(m$patient);delta<-sapply(c('lipid',names(sets)),function(g)sapply(id,function(p)m[m$patient==p&m$site=='GCPM',g]-m[m$patient==p&m$site=='GCPT',g]));d<-data.frame(patient=id,delta);write.table(d,file.path(O,'paired_program_differences.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
corres<-do.call(rbind,lapply(names(sets),function(n){z<-cor.test(d$lipid,d[[n]],method='spearman',exact=FALSE);data.frame(proxy=n,rho=unname(z$estimate),P=z$p.value,n=17)}));corres$FDR_BH<-p.adjust(corres$P,'BH');write.table(corres,file.path(O,'paired_change_correlations.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
write.table(m,file.path(O,'sample_program_scores.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
writeLines('exit_code=0',file.path(O,'COMPLETE.txt'));print(main);print(loo);print(lop);print(rr);print(corres)
